    @field_names = ['VFieldA', ...]
    -VFieldA: Dataset = float32(BxTxWxHxD)
      @dim_varying = [ True  True]
      @sample_varying = True
      @time_varying = True
    ... # Additional fields

  -t2_fields: Group
    @field_names: list[str] = ['TFieldA', ...]
    - TFieldA: Dataset = float32(BxTxWxHxD^2)
      @antisymmetric = False
      @dim_varying = [ True  True]
      @sample_varying = True
      @symmetric = True # Whether tensor is symmetric
      @time_varying = True
    ... # Additional fields
